const mails = await api.get("/mails");
const items = mails.items || [];
const refund = items.filter(m => (m.label || "").includes("환불") || (m.subject || "").includes("환불") || (m.body || "").includes("환불"));
const result = [];
for (const m of refund) {
  if (!m.customer_id) { result.push({ mail: m.id, label: m.label, customer: null }); continue; }
  const c = await api.get("/customers/" + m.customer_id);
  result.push({ mail: m.id, subject: m.subject, label: m.label, customer_id: m.customer_id, name: c.name, tier: c.tier });
}
return { total: items.length, refundCount: refund.length, result };

